56	int dcmi_call_dsmi_hot_reset(int device_logic_id)
57	{
58	    int ret;
59	
60	#ifndef _WIN32
61	    ret = dsmi_hot_reset_atomic(device_logic_id, DSMI_SUBCMD_HOTRESET_ASSEMBLE);
