75	int dcmi_reset_device_inband_param_check(int card_id, int device_id, enum dcmi_unit_type *device_type)
76	{
77	    int err;
78	
79	    if (!dcmi_is_in_phy_machine_root()) {
80	        gplog(LOG_OP, "Operation not permitted, only root user on physical machine can call this api.");
81	        return DCMI_ERR_CODE_OPER_NOT_PERMITTED;
82	    }
83	
84	    if (!dcmi_board_chip_type_is_ascend_950()) {
85	        err = dcmi_get_device_type(card_id, device_id, device_type);
86	        if (err != DCMI_OK) {
87	            gplog(LOG_ERR, "dcmi_get_device_type failed. err is %d.", err);
88	            return err;
89	        }
90	    }
91	
92	    if (dcmi_board_chip_type_is_ascend_910() || dcmi_board_chip_type_is_ascend_910b() ||
93	        dcmi_board_chip_type_is_ascend_910_93()) {
94	        gplog(LOG_OP, "The device does not support this api");
95	        return DCMI_ERR_CODE_NOT_SUPPORT;
96	    }
97	
98	    if (dcmi_board_type_is_model()) {
99	        gplog(LOG_OP, "The device does not support in-band reset.card_id %d device_id %d", card_id, device_id);
100	        return DCMI_ERR_CODE_NOT_SUPPORT;
101	    }
102	
103	    // 310p双芯片卡为smp模式，仅支持对device id 0进行预复位
104	    if ((dcmi_board_type_is_310p_duo_chips() == TRUE) && (device_id != 0)) {
105	        gplog(LOG_OP, "The device does not support in-band reset. device_id %d", device_id);
106	        return DCMI_ERR_CODE_NOT_SUPPORT;
107	    }
108	
109	    return DCMI_OK;
110	}
