112	int dcmi_reset_device_inband(int card_id, int device_id)
113	{
114	    int err;
115	    int device_logic_id = 0;
116	    enum dcmi_unit_type device_type = NPU_TYPE;
117	
118	    err = dcmi_reset_device_inband_param_check(card_id, device_id, &device_type);
119	    if (err != DCMI_OK) {
120	        return err;
121	    }
122	
123	    if (dcmi_board_chip_type_is_ascend_950()) {
124	        gplog(LOG_OP, "This product does not support this api.");
125	        return DCMI_ERR_CODE_NOT_SUPPORT;
126	    }
127	
128	    if (device_type == NPU_TYPE) {
129	        err = dcmi_get_device_logic_id(&device_logic_id, card_id, device_id);
130	        if (err != DCMI_OK) {
131	            gplog(LOG_ERR, "dcmi_get_device_logic_id failed. err is %d.", err);
132	            return err;
133	        }
134	        dcmi_npu_msn_env_clean(card_id);
135	        err = dcmi_call_dsmi_hot_reset(device_logic_id);
136	        if (err != DCMI_OK) {
137	            return err;
138	        }
139	        gplog(LOG_OP, "reset device inband success. card_id=%d, device_id=%d", card_id, device_id);
140	        return DCMI_OK;
141	    } else {
142	        gplog(LOG_OP, "device_type %d is not support.", device_type);
143	        return DCMI_ERR_CODE_NOT_SUPPORT;
144	    }
145	}
146	#endif
