148	int dcmi_set_device_pre_reset(int card_id, int device_id)
149	{
150	    int err;
151	    enum dcmi_unit_type device_type = NPU_TYPE;
152	    unsigned int main_board_id = 0;
153	
154	    // 支持物理机和A3、A5 Pod及Server特权容器场景
155	    main_board_id = dcmi_get_maindboard_id_inner();
156	    if (!dcmi_is_in_phy_machine_root() && !(dcmi_is_in_privileged_docker_root() &&
157	        ((dcmi_mainboard_is_arm_910_93(main_board_id))))) {
158	        gplog(LOG_OP, "Operation not permitted, only root user on physical machine can call this api.");
159	        return DCMI_ERR_CODE_OPER_NOT_PERMITTED;
160	    }
161	    
162	    if (!(dcmi_mainboard_is_arm_910_93(main_board_id))) {
163	        if (dcmi_check_device_reset_vnpu_mode(card_id) == DCMI_OK) {
164	            gplog(LOG_OP, "card_id %d is in vnpu mode can not reset.\n", card_id);
165	            return DCMI_ERR_CODE_OPER_NOT_PERMITTED;
166	        }
167	    }
168	
169	    err = dcmi_get_device_type(card_id, device_id, &device_type);
170	    if (err != DCMI_OK) {
171	        gplog(LOG_ERR, "dcmi_get_device_type failed. err is %d.", err);
172	        return err;
173	    }
174	
175	    // 310p双芯片卡为smp模式，仅支持对device id0进行复位
176	    if ((dcmi_board_type_is_310p_duo_chips()) && (device_id != 0)) {
177	        gplog(LOG_OP, "device_id %d is not support.", device_id);
178	        return DCMI_ERR_CODE_NOT_SUPPORT;
179	    }
180	
181	    if (device_type == NPU_TYPE) {
182	        err = dcmi_set_npu_device_pre_reset(card_id, device_id);
183	        if (err != DCMI_OK) {
184	            gplog(LOG_OP, "set pre reset failed. card_id=%d, device_id=%d, err=%d", card_id, device_id, err);
185	            return err;
186	        }
187	
188	        gplog(LOG_OP, "set pre reset success. card_id=%d, device_id=%d", card_id, device_id);
189	        return DCMI_OK;
190	    } else {
191	        gplog(LOG_OP, "device_type %d is not support.", device_type);
192	        return DCMI_ERR_CODE_NOT_SUPPORT;
193	    }
194	}
