196	STATIC int dcmi_check_permission_by_channel_type(const enum dcmi_reset_channel channel_type)
197	{
198	    if (channel_type != INBAND_CHANNEL) {
199	        if (!(dcmi_board_chip_type_is_ascend_910_93() ||
200	              dcmi_board_chip_type_is_ascend_950_pod() ||
201	              dcmi_board_chip_type_is_ascend_950_server()) || !dcmi_is_in_privileged_docker_root()) {
202	            gplog(LOG_OP, "Operation not permitted, only inband mode is supported on virtual machine or container.");
203	            return DCMI_ERR_CODE_OPER_NOT_PERMITTED;
204	        }
205	    }
206	    return DCMI_OK;
207	}
