209	int dcmi_check_910b_card_vm_docker(void)
210	{
211	    if ((dcmi_board_type_is_card() == TRUE) && (dcmi_board_chip_type_is_ascend_910b()) &&
212	        (dcmi_check_run_in_docker() || dcmi_check_run_in_vm())) {
213	            gplog(LOG_ERR, "Operation not permitted, this device can't call this api on virtual machine or container.");
214	            return DCMI_ERR_CODE_OPER_NOT_PERMITTED;
215	    }
216	    return DCMI_OK;
217	}
