219	int dcmi_check_device_reset_permission(const enum dcmi_reset_channel channel_type)
220	{
221	    int ret;
222	
223	    if (dcmi_check_run_not_root()) {
224	        gplog(LOG_OP, "Operation not permitted, only root user can call this api.");
225	        return DCMI_ERR_CODE_OPER_NOT_PERMITTED;
226	    }
227	
228	    if (!dcmi_is_in_phy_machine()) {
229	        ret = dcmi_check_permission_by_channel_type(channel_type);
230	        if (ret != DCMI_OK) {
231	            gplog(LOG_OP, "call dcmi_check_permission_by_channel_type failed. err is %d", ret);
232	            return ret;
233	        }
234	
235	        if ((!dcmi_board_chip_type_is_ascend_310()) &&
236	            (!dcmi_board_chip_type_is_ascend_310p()) &&
237	            (!dcmi_board_chip_type_is_ascend_910b()) &&
238	            (!dcmi_board_chip_type_is_ascend_910()) &&
239	            (!dcmi_board_chip_type_is_ascend_910_93()) &&
240	            (!dcmi_board_chip_type_is_ascend_950())) {
241	            gplog(LOG_OP, "Operation not permitted, this device can't call this api on virtual machine or container.");
242	            return DCMI_ERR_CODE_OPER_NOT_PERMITTED;
243	        }
244	    }
245	
246	    /* 910B标卡在容器和虚拟机场景不支持热复位 */
247	    ret = dcmi_check_910b_card_vm_docker();
248	    if (ret != DCMI_OK) {
249	        printf("This command cannot be executed on a VM or container.\n");
250	        return ret;
251	    }
252	
253	    /* 910B 支持物理机 + 特权容器 */
254	    if (dcmi_check_run_in_docker() &&
255	        (dcmi_board_chip_type_is_ascend_910b() || dcmi_board_chip_type_is_ascend_910_93() ||
256	        dcmi_board_chip_type_is_ascend_950())) {
257	        ret = dcmi_check_a2_a3_a5_device_reset_docker_permission();
258	        if (ret != DCMI_OK) {
259	            gplog(LOG_ERR, "call dcmi_check_a2_a3_a5_device_reset_docker_permission failed. err is %d.", ret);
260	            return ret;
261	        }
262	    }
263	
264	    return DCMI_OK;
265	}
