267	int dcmi_check_device_reset_vnpu_mode(int card_id)
268	{
269	    int ret = 0;
270	    int hccs_status = HCCS_OFF;
271	    unsigned int env_flag;
272	    int vir_flag;
273	
274	    if (dcmi_check_run_in_docker() || dcmi_check_run_in_vm()) {
275	        // 在虚拟机或容器里，通过chip name判断是否算力切分
276	        // 获取当前场景信息
277	        ret = dcmi_get_environment_flag(&env_flag);
278	        if (ret != DCMI_OK) {
279	            gplog(LOG_ERR, "Failed to get dcmi_get_environment_flag.\n");
280	            return DCMI_ERR_CODE_INNER_ERR;
281	        }
282	
283	        // 获取是否算力切分
284	        ret = dcmi_check_vnpu_chip_is_vir(card_id, 0, &vir_flag);
285	        if (ret != DCMI_OK) {
286	            gplog(LOG_ERR, "Failed to get dcmi_check_vnpu_chip_is_vir.\n");
287	            return DCMI_ERR_CODE_INNER_ERR;
288	        }
289	
290	        if ((env_flag == ENV_PHYSICAL_PLAIN_CONTAINER) && (vir_flag == 1)) {
291	            return DCMI_OK;
292	        }
293	    } else {
294	        if (dcmi_board_chip_type_is_ascend_910b()) {
295	            // 当前只有910B需要查询hccs互联状态
296	            ret = dcmi_get_hccs_status(card_id, 0, &hccs_status);
297	            if (ret != DCMI_OK) {
298	                gplog(LOG_ERR, "Failed to get dcmi_get_hccs_status.\n");
299	                return DCMI_ERR_CODE_INNER_ERR;
300	            }
301	        }
302	
303	        if (hccs_status == HCCS_ON) {
304	            if (dcmi_check_card_is_split_phy(0xff) == TRUE) {
305	                return DCMI_OK;
306	            }
307	        } else {
308	            if (dcmi_check_card_is_split_phy(card_id) == TRUE) {
309	                return DCMI_OK;
310	            }
311	        }
312	    }
313	
314	    return DCMI_ERR_CODE_INNER_ERR;
315	}
