317	int execute_npu_reset(int card_id, int device_id, enum dcmi_reset_channel channel_type)
318	{
319	    int err;
320	    
321	    switch (channel_type) {
322	        case INBAND_CHANNEL:
323	            err = dcmi_set_npu_device_reset_inband(card_id, device_id);
324	            break;
325	        case OUTBAND_CHANNEL:
326	            err = dcmi_set_npu_device_reset_outband(card_id, device_id);
327	            break;
328	        default:
329	            gplog(LOG_ERR, "channel_type %d is error.", channel_type);
330	            return DCMI_ERR_CODE_NOT_SUPPORT;
331	    }
332	    
333	    return err;
334	}
