336	int dcmi_set_device_reset(int card_id, int device_id, enum dcmi_reset_channel channel_type)
337	{
338	    int err;
339	    enum dcmi_unit_type device_type = NPU_TYPE;
340	
341	    err = dcmi_check_device_reset_permission(channel_type);
342	    if (err != DCMI_OK) {
343	        return err;
344	    }
345	
346	    if (card_id == ALL_DEVICE_RESET_CARD_ID && channel_type != INBAND_CHANNEL) {
347	        gplog(LOG_ERR, "This card_id is not supported in this scenario.");
348	        return DCMI_ERR_CODE_INVALID_PARAMETER;
349	    }
350	
351	    if (card_id != ALL_DEVICE_RESET_CARD_ID ||
352	        !dcmi_board_chip_type_is_ascend_910_93()) {
353	        if (dcmi_board_chip_type_is_ascend_950()) {
354	            err = dcmiv2_get_device_type(card_id, &device_type);
355	        } else {
356	            err = dcmi_get_device_type(card_id, device_id, &device_type);
357	        }
358	        if (err != DCMI_OK) {
359	            gplog(LOG_ERR, "dcmi_get_device_type failed. err is %d.", err);
360	            return err;
361	        }
362	    }
363	
364	    // Atlas 300i-duo为smp模式，仅支持对device id0进行复位
365	    if ((dcmi_board_type_is_310p_duo_chips()) && (device_id != 0)) {
366	        gplog(LOG_OP, "device_id %d is not support.", device_id);
367	        return DCMI_ERR_CODE_NOT_SUPPORT;
368	    }
369	
370	    if (device_type != NPU_TYPE) {
371	        gplog(LOG_OP, "device_type %d is not support.", device_type);
372	        return DCMI_ERR_CODE_NOT_SUPPORT;
373	    }
374	
375	    err = execute_npu_reset(card_id, device_id, channel_type);
376	    if (err != DCMI_OK) {
377	        gplog(LOG_OP, "reset failed. card_id=%d, device_id=%d, channel_type=%d, err=%d", card_id, device_id,
378	            channel_type, err);
379	        return err;
380	    }
381	
382	    gplog(LOG_OP, "reset success. card_id=%d, device_id=%d, channel_type=%d", card_id, device_id, channel_type);
383	    return DCMI_OK;
384	}
