427	int dcmi_get_npu_outband_reset_state(int card_id, int device_id, unsigned char *reset_state)
428	{
429	#ifdef _WIN32
430	    return DCMI_ERR_CODE_NOT_SUPPORT;
431	#else
432	    int ret, logic_id;
433	    int pcie_slot_id; /* pcie卡的槽位号 */
434	
435	    if (dcmi_board_type_is_card() != TRUE) {
436	        return DCMI_ERR_CODE_NOT_SUPPORT;
437	    }
438	
439	    // 获取pcie卡的槽位号
440	    if (dcmi_board_chip_type_is_ascend_950()) {
441	        ret = dcmiv2_get_device_logic_id(&logic_id, card_id, device_id);
442	        if (ret != DCMI_OK) {
443	            gplog(LOG_ERR, "dcmiv2_get_device_logic_id failed. (ret=%d)", ret);
444	            return ret;
445	        }
446	
447	        ret = dcmiv2_get_device_pcie_slot_id(logic_id, &pcie_slot_id);
448	        if (ret != DCMI_OK) {
449	            gplog(LOG_ERR, "Call dcmiv2_get_pcie_slot failed. (ret=%d)", ret);
450	            return ret;
451	        }
452	    } else {
453	        ret = dcmi_get_card_pcie_slot(card_id, &pcie_slot_id);
454	        if (ret != DCMI_OK) {
455	            gplog(LOG_ERR, "Call dcmi_get_pcie_slot failed. (ret=%d)", ret);
456	            return ret;
457	        }
458	    }
459	
460	    // 用该函数查询复位结果,用以判断通路状态共获取两次
461	    ret = dcmi_ipmi_get_npu_reset_state(pcie_slot_id, device_id, reset_state);
462	    if (ret != DCMI_OK) {
463	        sleep(1); // 延迟1s
464	        ret = dcmi_ipmi_get_npu_reset_state(pcie_slot_id, device_id, reset_state);
465	        if (ret != DCMI_OK) {
466	            gplog(LOG_ERR, "Call dcmi_ipmi_get_npu_reset_state failed. err is %d.", ret);
467	            return ret;
468	        }
469	    }
470	
471	    return DCMI_OK;
472	#endif
473	}
