475	int dcmi_get_device_outband_channel_state(int card_id, int device_id, int *channel_state)
476	{
477	    enum dcmi_unit_type device_type = NPU_TYPE;
478	    int ret;
479	    unsigned int main_board_id = 0;
480	
481	    // 支持物理机和A3、A5 Pod及Server特权容器场景
482	    main_board_id = dcmi_get_maindboard_id_inner();
483	    if (!dcmi_is_in_phy_machine_root() && !(dcmi_is_in_privileged_docker_root() &&
484	        (dcmi_mainboard_is_arm_910_93(main_board_id) ||
485	         dcmi_board_chip_type_is_ascend_950_pod() ||
486	         dcmi_board_chip_type_is_ascend_950_server()))) {
487	        gplog(LOG_ERR, "Operation not permitted, only root user on physical machine can call this api.");
488	        return DCMI_ERR_CODE_OPER_NOT_PERMITTED;
489	    }
490	
491	    if (channel_state == NULL) {
492	        gplog(LOG_ERR, "channel state is invalid.");
493	        return DCMI_ERR_CODE_INVALID_PARAMETER;
494	    }
495	
496	    if (dcmi_board_chip_type_is_ascend_950()) {
