605	int dcmi_pre_reset_brother_card_set_flag(int master_logic_id, int slaver_logic_id,
606	                                         int brother_master_logic_id, int brother_slave_logic_id, int brother_card_id)
607	{
608	    int ret;
609	    ret = dsmi_hot_reset_atomic(master_logic_id, DSMI_SUBCMD_HOTRESET_SETFLAG);
610	    if (ret != DSMI_OK) {
611	        gplog(LOG_ERR, "call dsmi_hot_reset_atomic failed. err is %d.master_logic_id=%d", ret, master_logic_id);
612	        return dcmi_convert_error_code(ret);
613	    }
614	    ret = dsmi_hot_reset_atomic(slaver_logic_id, DSMI_SUBCMD_HOTRESET_SETFLAG);
615	    if (ret != DSMI_OK) {
616	        (void)dsmi_hot_reset_atomic(master_logic_id, DSMI_SUBCMD_HOTRESET_CLEARFLAG);
617	        gplog(LOG_ERR, "call dsmi_hot_reset_atomic failed. err is %d.slaver_logic_id=%d", ret, slaver_logic_id);
618	        return dcmi_convert_error_code(ret);
619	    }
620	    if (brother_card_id != -1) {
621	        ret = dsmi_hot_reset_atomic(brother_master_logic_id, DSMI_SUBCMD_HOTRESET_SETFLAG);
622	        if (ret != DSMI_OK) {
623	            (void)dsmi_hot_reset_atomic(master_logic_id, DSMI_SUBCMD_HOTRESET_CLEARFLAG);
624	            (void)dsmi_hot_reset_atomic(slaver_logic_id, DSMI_SUBCMD_HOTRESET_CLEARFLAG);
625	            gplog(LOG_ERR, "call dsmi_hot_reset_atomic failed. err is %d.brother_master_logic_id=%d",
626	                ret, brother_master_logic_id);
627	            return dcmi_convert_error_code(ret);
628	        }
629	        ret = dsmi_hot_reset_atomic(brother_slave_logic_id, DSMI_SUBCMD_HOTRESET_SETFLAG);
630	        if (ret != DSMI_OK) {
631	            (void)dsmi_hot_reset_atomic(master_logic_id, DSMI_SUBCMD_HOTRESET_CLEARFLAG);
632	            (void)dsmi_hot_reset_atomic(slaver_logic_id, DSMI_SUBCMD_HOTRESET_CLEARFLAG);
633	            (void)dsmi_hot_reset_atomic(brother_master_logic_id, DSMI_SUBCMD_HOTRESET_CLEARFLAG);
634	            gplog(LOG_ERR, "call dsmi_hot_reset_atomic failed. err is %d.brother_slave_logic_id=%d",
635	                ret, brother_slave_logic_id);
636	            return dcmi_convert_error_code(ret);
637	        }
638	    }
639	    return dcmi_convert_error_code(ret);
640	}
