642	int dcmi_pre_reset_brother_card_outbind(int card_id, int brother_card_id)
643	{
644	    int ret ;
645	    int master_logic_id, slaver_logic_id, brother_master_logic_id, brother_slave_logic_id;
646	
647	    ret = dcmi_get_device_logic_id(&master_logic_id, card_id, 0);
648	    ret |= dcmi_get_device_logic_id(&slaver_logic_id, card_id, 1);
649	    if (brother_card_id != -1) {
650	        ret |= dcmi_get_device_logic_id(&brother_master_logic_id, brother_card_id, 0);
651	        ret |= dcmi_get_device_logic_id(&brother_slave_logic_id, brother_card_id, 1);
652	    }
653	    if (ret != 0) {
654	        gplog(LOG_ERR, "get_logicid failed. err is %d. card_id=%d, brother_card_id=%d", ret, card_id, brother_card_id);
655	        return DCMI_ERR_CODE_INNER_ERR;
656	    }
657	
658	    /* 依次判断4个device是否可以复位 */
659	    ret = dcmi_pre_reset_brother_card_set_flag(master_logic_id, slaver_logic_id,
660	                                               brother_master_logic_id, brother_slave_logic_id, brother_card_id);
661	    if (ret != DCMI_OK) {
662	        return ret;
663	    }
664	
665	    dcmi_npu_msn_env_clean(card_id);
666	    (void)dsmi_hot_reset_atomic(master_logic_id, DSMI_SUBCMD_HOTRESET_UNBIND);
667	    (void)dsmi_hot_reset_atomic(slaver_logic_id, DSMI_SUBCMD_HOTRESET_UNBIND);
668	    if (brother_card_id != -1) {
669	        dcmi_npu_msn_env_clean(brother_card_id);
670	        (void)dsmi_hot_reset_atomic(brother_master_logic_id, DSMI_SUBCMD_HOTRESET_UNBIND);
671	        (void)dsmi_hot_reset_atomic(brother_slave_logic_id, DSMI_SUBCMD_HOTRESET_UNBIND);
672	    }
673	    (void)dsmi_hot_reset_atomic(slaver_logic_id, DSMI_SUBCMD_HOTRESET_REMOVE);
674	    (void)dsmi_hot_reset_atomic(master_logic_id, DSMI_SUBCMD_HOTRESET_REMOVE);
675	    if (brother_card_id != -1) {
676	        (void)dsmi_hot_reset_atomic(brother_slave_logic_id, DSMI_SUBCMD_HOTRESET_REMOVE);
677	        (void)dsmi_hot_reset_atomic(brother_master_logic_id, DSMI_SUBCMD_HOTRESET_REMOVE);
678	    }
679	    return 0;
680	}
