682	int dcmi_pre_reset_device(int card_id, int brother_card_id, int id)
683	{
684	    int ret;
685	    unsigned int main_board_id = 0;
686	
687	#ifndef _WIN32
688	    main_board_id = dcmi_get_maindboard_id_inner();
689	    if (dcmi_mainboard_is_arm_910_93(main_board_id)) {
690	        // A3场景下判断cpld版本是否支持
691	        ret = dcmi_check_device_cpld_version(card_id);
692	        if (ret != DCMI_OK) {
693	            gplog(LOG_ERR, "call dcmi_check_device_cpld_version failed, id=%d. err is %d.", card_id, ret);
694	            return ret;
695	        }
696	        if (brother_card_id != -1) {
697	            ret = dcmi_check_device_cpld_version(brother_card_id);
698	            if (ret != DCMI_OK) {
699	                gplog(LOG_ERR, "call dcmi_check_device_cpld_version failed, id=%d. err is %d.", brother_card_id, ret);
700	                return ret;
701	            }
702	
703	            ret = dcmi_clear_running_proc();
704	            if (ret != DCMI_OK) {
705	                gplog(LOG_ERR, "call dcmi_clear_running_proc failed, id=%d. err is %d.", card_id, ret);
706	                return ret;
707	            }
708	        }
709	        ret = dcmi_pre_reset_brother_card_outbind(card_id, brother_card_id);
710	        return ret;
711	    }
712	    if (dcmi_board_chip_type_is_ascend_910b() || dcmi_board_chip_type_is_ascend_910_93()) {
713	        ret = dcmi_clear_running_proc();
714	        if (ret != DCMI_OK) {
715	            gplog(LOG_ERR, "call dcmi_clear_running_proc failed, id=%d. err is %d.", card_id, ret);
716	            return ret;
717	        }
718	    }
719	    ret = dsmi_hot_reset_atomic(id, DSMI_SUBCMD_PRERESET_ASSEMBLE);
720	#else
721	    ret = dsmi_pre_reset_soc(id, 0);
722	#endif
723	    if (ret != DSMI_OK) {
724	        gplog(LOG_ERR, "pre reset soc failed, id=%d. err is %d.", id, ret);
725	        return dcmi_convert_error_code(ret);
726	    }
727	
728	    return ret;
729	}
