731	int dcmi_set_npu_device_pre_reset(int card_id, int device_id)
732	{
733	    unsigned int device_phy_id = 0, main_board_id = 0;
734	    struct dcmi_card_info *card_info = NULL;
735	    int brother_card_id = -1;
736	
737	    main_board_id = dcmi_get_maindboard_id_inner();
738	    if (dcmi_board_type_is_card() != TRUE && !dcmi_mainboard_is_arm_910_93(main_board_id) &&
739	        !dcmi_board_chip_type_is_ascend_950_pod() && !dcmi_board_chip_type_is_ascend_950_server()) {
740	        return DCMI_ERR_CODE_NOT_SUPPORT;
741	    }
742	    // 获取卡的信息
743	    int ret = dcmi_get_card_info(card_id, &card_info);
744	    if (ret != DCMI_OK) {
745	        gplog(LOG_ERR, "call dcmi_get_card_info failed, id=%d. err is %d.", card_id, ret);
746	        return ret;
747	    }
748	    // A3场景下获取网口互助卡的信息
749	    if (dcmi_mainboard_is_arm_910_93(main_board_id)) {
750	        ret = dcmi_get_netdev_brother_device(card_id, device_id, &brother_card_id);
751	        if (ret != DCMI_OK) {
752	            gplog(LOG_ERR, "call dcmi_get_net_dev_brother_device failed. err is %d.", ret);
753	            return ret;
754	        }
755	        g_brother_card_id[card_id] = brother_card_id;
756	    }
757	
758	    int device_logic_id = card_info->device_info[device_id].logic_id;
759	    ret = dsmi_get_phyid_from_logicid(device_logic_id, &device_phy_id);
760	    if (ret != DSMI_OK) {
761	        gplog(LOG_ERR, "call dsmi_get_phyid_from_logicid failed. err is %d.", ret);
762	        return dcmi_convert_error_code(ret);
763	    }
764	
765	    int id = (dcmi_board_chip_type_is_ascend_310()) ? (int)device_phy_id : device_logic_id;
766	    ret = dcmi_pre_reset_device(card_id, brother_card_id, id);
767	    if (ret != DCMI_OK) {
768	        gplog(LOG_ERR, "call dcmi_pre_reset_device failed, id=%d. err is %d.", card_id, ret);
769	        return ret;
770	    }
771	
772	    sleep(1);
773	#ifndef _WIN32
774	    // 关闭上游端口
775	    if (!(dcmi_mainboard_is_arm_910_93(main_board_id) || dcmi_board_chip_type_is_ascend_950())) {
776	        ret = dcmi_set_npu_device_close_pcie_upstream(card_id, device_id, card_info);
777	        if (ret != DCMI_OK) {
778	            gplog(LOG_ERR, "call dcmi_set_npu_device_close_pcie_upstream failed, id=%d. err is %d.", card_id, ret);
779	            return ret;
780	        }
781	    }
782	#endif
783	
784	    return ret;
785	}
