1040	int dcmi_match_proc_info(char *proc_name, int proc_len, int pid, bool *found_flag)
1041	{
1042	    int ret;
1043	    char *name_start = NULL;
1044	    char *name_end = NULL;
1045	    FILE *fp = NULL;
1046	    char status_path[DCMI_BUFFER_SIZE] = {0};
1047	    char line[LINE_MAX_LEN];
1048	
1049	    ret = sprintf_s(status_path, DCMI_BUFFER_SIZE, "/proc/%d/status", pid);
1050	    if (ret <= 0) {
1051	        gplog(LOG_ERR, "sprintf_s failed.");
1052	        return DCMI_ERR_CODE_SECURE_FUN_FAIL;
1053	    }
1054	
1055	    // 1.查看status_path是否存在
1056	    if (access(status_path, F_OK) != 0) {
1057	        gplog(LOG_INFO, "%s isn't exist!", status_path);
1058	        return DCMI_OK; // 此处为进程不存在，不影响热复位功能使用
1059	    }
1060	
1061	    // 2. 打开 status 文件
1062	    fp = fopen(status_path, "r");
1063	    if (fp == NULL) {
1064	        gplog(LOG_ERR, "open /proc/%d/status failed", pid);
1065	        return DCMI_ERR_CODE_FILE_OPERATE_FAIL;
1066	    }
1067	
1068	    // 3. 逐行读取，查找 "Name:" 字段
1069	    while (fgets(line, sizeof(line), fp) != NULL) {
1070	        // 检查是否以 "Name:" 开头（忽略大小写）
1071	        if (strncmp(line, "Name:", CMP_NAME_MAX_SIZE) == 0) {
1072	            // 提取进程名（去掉开头的 "Name:" 和空白）
1073	            name_start = line + CMP_NAME_MAX_SIZE;
1074	            // 跳过空白字符
1075	            while (*name_start && isspace(*name_start)) {
1076	                name_start++;
1077	            }
1078	            // 提取到行尾或下一个空格
1079	            name_end = name_start;
1080	            while (*name_end && !isspace(*name_end)) {
1081	                name_end++;
1082	            }
1083	            *name_end = '\0';  // 截断
1084	
1085	            if (strcmp(name_start, proc_name) == 0) {
1086	                *found_flag = TRUE;
1087	                break;
1088	            }
1089	            break;
1090	        }
1091	    }
1092	
1093	    ret = fclose(fp);
1094	    if (ret != 0) {
1095	        gplog(LOG_ERR, "close /proc/%d/status failed", pid);
1096	        return DCMI_ERR_CODE_FILE_OPERATE_FAIL;
1097	    }
1098	
1099	    return DCMI_OK;
1100	}
