1102	int dcmi_get_pid_and_proc_name(char *buffer, char *process_name, int *pid, int *copy_len, bool *valid_flag)
1103	{
1104	    int ret;
1105	    int para_index = 0;
1106	    int tmp_copy_len = 0;
1107	    int token_len = 0;
1108	    char *token = NULL;
1109	    char *context = NULL;
1110	    char target_string[WHITE_PROC_TARGET_MAX_SIZE] = "AllowKilledWhenResetNPU";
1111	
1112	    token = strtok_s(buffer, ":", &context);
1113	    while (token != NULL) {
1114	        token_len = strlen(token);
1115	        if (para_index == 0) {
1116	            ret = strcmp(token, target_string);
1117	            if (ret != 0) {
1118	                gplog(LOG_INFO, "call strcmp failed, err is %d.", ret);
1119	                return DCMI_OK; // 格式内容不匹配，不影响功能使用
1120	            }
1121	        } else if (para_index == WHITE_PROC_NAME_OFFSET) {
1122	            tmp_copy_len = (token_len < NAME_MAX_SIZE) ? token_len : NAME_MAX_SIZE;
1123	            ret = memcpy_s(process_name, sizeof(char) * tmp_copy_len, token, sizeof(char) * tmp_copy_len);
1124	            if (ret != 0) {
1125	                gplog(LOG_ERR, "call memcpy_s failed, err is %d.", ret);
1126	                return DCMI_ERR_CODE_MEM_OPERATE_FAIL;
1127	            }
1128	            process_name[tmp_copy_len] = '\0';
1129	        } else if (para_index == WHITE_PROC_PID_OFFSET) {
1130	            ret = dcmi_check_pid_valid(token);
1131	            if (ret != DCMI_OK) {
1132	                // 由于对于非法pid的处理是选择跳过，不会影响功能使用，所以此处不记录错误日志
1133	                gplog(LOG_INFO, "pid is invalid. pid = %s.", token);
1134	                return DCMI_OK;
1135	            }
1136	            *pid = (int)strtol(token, NULL, BASE_TEN_NUMERAL_SYSTEM);
1137	        }
1138	        token = strtok_s(NULL, ":", &context);
1139	        para_index++;
1140	    }
1141	
1142	    if (para_index != WHITE_PROC_MAX_OFFSET) {
1143	        gplog(LOG_INFO, "para_index is incorrect!");
1144	        return DCMI_OK; // 由于此处是文件格式内容不匹配，不影响功能使用，所以此处返回DCMI_OK
1145	    }
1146	
1147	    *copy_len = tmp_copy_len;
1148	    *valid_flag = TRUE;
1149	    return DCMI_OK;
1150	}
