1188	int dcmi_check_if_occupy_proc_exist(OCCUPIED_PROC_INFO *info, bool *need_kill)
1189	{
1190	    int i;
1191	    int ret;
1192	    bool tmp_flag = false;
1193	
1194	    for (i = 0; i < info->pid_cnt; i++) {
1195	        if (info->state[i] == PROC_STATE_DEAD) {
1196	            continue;
1197	        }
1198	        ret = kill(info->pid[i], 0);
1199	        if (ret == -1) {
1200	            info->state[i] = PROC_STATE_DEAD;
1201	            gplog(LOG_INFO, "PID %d Has been successfully terminated", info->pid[i]);
1202	            continue;
1203	        } else if (ret == 0) {
1204	            gplog(LOG_INFO, "PID %d is still alive", info->pid[i]);
1205	            tmp_flag = true;
1206	        } else {
1207	            gplog(LOG_ERR, "Failed to send the zero signal to the process(%d)", info->pid[i]);
1208	            return DCMI_ERR_CODE_INNER_ERR;
1209	        }
1210	    }
1211	
1212	    *need_kill = tmp_flag;
1213	    return DCMI_OK;
1214	}
