1216	int dcmi_kill_all_occupy_npu_proc(OCCUPIED_PROC_INFO *info)
1217	{
1218	    int i;
1219	    int try_cnt = 0;
1220	    int ret;
1221	    bool need_kill = true;
1222	    while (try_cnt < KILL_MAX_TRY_CNT && need_kill) {
1223	        for (i = 0; i < info->pid_cnt; i++) {
1224	            if (info->state[i] == PROC_STATE_DEAD) {
1225	                continue;
1226	            }
1227	
1228	            ret = kill(info->pid[i], 0);
1229	            if (ret != 0) {
1230	                info->state[i] = PROC_STATE_DEAD;
1231	                gplog(LOG_INFO, "this process is dead! pid = %d", info->pid[i]);
1232	                continue;
1233	            }
1234	
1235	            ret = kill(info->pid[i], SIGKILL);
1236	            if (ret != 0) {
1237	                gplog(LOG_INFO, "Failed to kill process(%d), try_cnt = %d", info->pid[i], try_cnt);
1238	                return DCMI_ERR_CODE_INNER_ERR;
1239	            }
1240	        }
1241	
1242	        sleep(WHITE_PROC_KILL_WAIT_TIME);
1243	
1244	        ret = dcmi_check_if_occupy_proc_exist(info, &need_kill);
1245	        if (ret != DCMI_OK) {
1246	            gplog(LOG_ERR, "call dcmi_check_if_occupy_proc_exist fail! ret = %d", ret);
1247	            return ret;
1248	        }
1249	
1250	        try_cnt++;
1251	    }
1252	    return DCMI_OK;
1253	}
