1256	{
1257	    int ret;
1258	    int pid = -1;
1259	    int proc_num = 0;
1260	    int buff_len = 0;
1261	    bool string_match_flag = FALSE;
1262	    char buffer[WHITE_PROC_BUFFER_SIZE];
1263	
1264	    // 逐行读取文本内容，抠出白名单进程信息
1265	    while ((fgets(buffer, sizeof(buffer), fp) != NULL) && proc_num < WHITE_PROC_MAX_NUM) {
1266	        string_match_flag = FALSE;
1267	        proc_num++;
