1270	        if (buff_len > 0 && buffer[buff_len - 1] == '\n') {
1271	            buffer[buff_len - 1] = '\0';
1272	        }
1273	        // 删除buffer中的空格
1274	        dcmi_remove_all_whitespace(buffer, WHITE_PROC_BUFFER_SIZE);
