1280	        }
1281	        if (!string_match_flag) {
1282	            gplog(LOG_INFO, "Format mismatch, ignore: %s", buffer);
1283	            continue;
1284	        }
1285	
1286	        // 判断进程是否存在
1287	        ret = kill(pid, 0);
1288	        if (ret == -1) {
1289	            gplog(LOG_INFO, "The process does not exist, pid = %d", pid);
1290	            continue;
1291	        }
1292	
1293	        // 满足条件将pid存到info结构体中
1294	        proc_info->pid[proc_info->proc_num] = pid;
