1514	int dcmi_reset_brother_card(int card_id, int brother_card_id)
1515	{
1516	    int ret;
1517	    int master_logic_id, slaver_logic_id, brother_master_logic_id, brother_slave_logic_id;
1518	
1519	    ret = dcmi_get_device_logic_id(&master_logic_id, card_id, 0);
1520	    ret |= dcmi_get_device_logic_id(&slaver_logic_id, card_id, 1);
1521	    if (brother_card_id != -1) {
1522	        ret |= dcmi_get_device_logic_id(&brother_master_logic_id, brother_card_id, 0);
1523	        ret |= dcmi_get_device_logic_id(&brother_slave_logic_id, brother_card_id, 1);
1524	    }
1525	    if (ret != 0) {
1526	        gplog(LOG_ERR, "get_logicid failed. err is %d. card_id=%d, brother_card_id=%d", ret, card_id, brother_card_id);
1527	        return DCMI_ERR_CODE_INNER_ERR;
1528	    }
1529	
1530	    /* 依次判断4个device是否可以复位 */
1531	    ret = dcmi_pre_reset_brother_card_set_flag(master_logic_id, slaver_logic_id,
1532	                                               brother_master_logic_id, brother_slave_logic_id, brother_card_id);
1533	    if (ret != DCMI_OK) {
1534	        return ret;
1535	    }
1536	
1537	    dcmi_npu_msn_env_clean(card_id);
1538	    (void)dsmi_hot_reset_atomic(master_logic_id, DSMI_SUBCMD_HOTRESET_UNBIND);
1539	    (void)dsmi_hot_reset_atomic(slaver_logic_id, DSMI_SUBCMD_HOTRESET_UNBIND);
1540	    if (brother_card_id != -1) {
1541	        dcmi_npu_msn_env_clean(brother_card_id);
1542	        (void)dsmi_hot_reset_atomic(brother_master_logic_id, DSMI_SUBCMD_HOTRESET_UNBIND);
1543	        (void)dsmi_hot_reset_atomic(brother_slave_logic_id, DSMI_SUBCMD_HOTRESET_UNBIND);
1544	    }
1545	    (void)dsmi_hot_reset_atomic(slaver_logic_id, DSMI_SUBCMD_HOTRESET_REMOVE);
1546	    if (brother_card_id != -1) {
1547	        (void)dsmi_hot_reset_atomic(brother_slave_logic_id, DSMI_SUBCMD_HOTRESET_REMOVE);
1548	    }
1549	    (void)dsmi_hot_reset_atomic(master_logic_id, DSMI_SUBCMD_HOTRESET_RESET);
1550	
1551	    if (brother_card_id != -1) {
1552	        (void)dsmi_hot_reset_atomic(brother_master_logic_id, DSMI_SUBCMD_HOTRESET_RESET);
1553	    }
1554	    /* 兄弟卡复位多增加2秒 */
1555	    sleep(2);
1556	    (void)dsmi_hot_reset_atomic(master_logic_id, DSMI_SUBCMD_HOTRESET_REMOVE);
1557	    if (brother_card_id != -1) {
1558	        (void)dsmi_hot_reset_atomic(brother_master_logic_id, DSMI_SUBCMD_HOTRESET_REMOVE);
1559	    }
1560	
1561	    (void)dsmi_hot_reset_atomic(slaver_logic_id, DSMI_SUBCMD_HOTRESET_RESCAN);
1562	    (void)dsmi_hot_reset_atomic(master_logic_id, DSMI_SUBCMD_HOTRESET_RESCAN);
1563	    if (brother_card_id != -1) {
1564	        (void)dsmi_hot_reset_atomic(brother_slave_logic_id, DSMI_SUBCMD_HOTRESET_RESCAN);
1565	        (void)dsmi_hot_reset_atomic(brother_master_logic_id, DSMI_SUBCMD_HOTRESET_RESCAN);
1566	    }
1567	    return 0;
1568	}
