1599	            (dcmi_is_in_phy_machine_root() || dcmi_check_run_in_privileged_docker()))) {
1600	            gplog(LOG_ERR, "This card_id is not supported in this scenario.");
1601	            return DCMI_ERR_CODE_INVALID_PARAMETER;
1602	        }
1603	        *hccs_status = HCCS_ON;
1604	        return DCMI_OK;
1605	    }
1606	
1607	    if (dcmi_board_chip_type_is_ascend_910b()) {
