1614	        // 910_93不支持虚拟机内热复位
1615	        if (!dcmi_is_in_phy_machine() && !dcmi_check_run_in_privileged_docker()) {
1616	            gplog(LOG_OP, "VMs or dockers users are not support in-band reset.");
1617	            return DCMI_ERR_CODE_NOT_SUPPORT;
