1625	int dcmi_set_npu_device_reset_inband(int card_id, int device_id)
1626	{
1627	    int ret, device_logic_id = 0, brother_card_id = 0, hccs_status = HCCS_OFF;
1628	
1629	    if (dcmi_board_type_is_card() != TRUE && dcmi_board_type_is_server() != TRUE &&
1630	        dcmi_board_type_is_model() != TRUE) {
1631	        gplog(LOG_OP, "The device does not support in-band reset. card_id=%d device_id=%d", card_id, device_id);
1632	        return DCMI_ERR_CODE_NOT_SUPPORT;
1633	    }
1634	
1635	    ret = dcmi_get_hccs_status_inband(card_id, device_id, &hccs_status);
1636	    if (ret != DCMI_OK) {
1637	        gplog(LOG_ERR, "call dcmi_get_hccs_status_inband failed. err is %d.", ret);
1638	        return ret;
1639	    }
1640	
1641	    if (card_id != ALL_DEVICE_RESET_CARD_ID) {
1642	        if (!dcmi_board_chip_type_is_ascend_950()) {
1643	            ret = dcmi_get_device_logic_id(&device_logic_id, card_id, device_id);
1644	        } else {
1645	            ret = dcmiv2_get_device_logic_id(&device_logic_id, card_id, device_id);
1646	        }
1647	    }
1648	
1649	    /* hccs互联，走全片复位 */
1650	    if (hccs_status == HCCS_ON) {
1651	        return hccs_reset_all();
1652	    }
1653	
1654	    if (dcmi_board_chip_type_is_ascend_910_93() || dcmi_board_chip_type_is_ascend_910b()) {
1655	        ret = dcmi_clear_running_proc();
1656	        if (ret != 0) {
1657	            gplog(LOG_ERR, "call dcmi_clear_running_proc failed, card_id=%d. err is %d.", card_id, ret);
1658	            return ret;
1659	        }
1660	    }
1661	
1662	    if (dcmi_board_chip_type_is_ascend_910_93()) {
1663	        ret = dcmi_get_netdev_brother_device(card_id, device_id, &brother_card_id);
1664	        if (ret != 0) {
1665	            gplog(LOG_ERR, "get_net_dev_brother_device failed. err is %d.", ret);
1666	            return ret;
1667	        }
1668	        return dcmi_reset_brother_card(card_id, brother_card_id);
1669	    }
1670	    dcmi_npu_msn_env_clean(card_id);
1671	
1672	    ret = dcmi_call_dsmi_hot_reset(device_logic_id);
1673	    if (ret == DCMI_OK) {
1674	        gplog(LOG_OP, "Resetting npu successfully by inband. card_id=%d, device_id=%d.", card_id, device_id);
1675	    }
1676	
1677	    return ret;
1678	}
