1728	static int dcmi_set_npu_device_reset(int card_id, int device_id, int outband_id, int pcie_slot_id)
1729	{
1730	    unsigned char reset_state = 0x01; /* 默认是复位失败 */
1731	    int retry_times;
1732	    int set_ret;
1733	    int get_ret = 0;
1734	    unsigned int device_phy_id = 0;
1735	    struct dcmi_card_info *card_info = NULL;
1736	    int ret;
1737	
1738	    if (dcmi_board_chip_type_is_ascend_950_pod() || dcmi_board_chip_type_is_ascend_950_server()) {
1739	        ret = dcmi_get_card_info(card_id, &card_info);
1740	        if (ret != DCMI_OK) {
1741	            gplog(LOG_ERR, "call dcmi_get_card_info failed, id=%d. err is %d.", card_id, ret);
1742	            return ret;
1743	        }
1744	        ret = dsmi_get_phyid_from_logicid(card_info->device_info[device_id].logic_id, &device_phy_id);
1745	        if (ret != DSMI_OK) {
1746	            gplog(LOG_ERR, "call dsmi_get_phyid_from_logicid failed. err is %d.", ret);
1747	            return dcmi_convert_error_code(ret);
1748	        }
1749	    }
1750	
1751	    for (retry_times = 0; retry_times < MAX_RETRY_CNT; retry_times++) {
1752	        if (dcmi_board_chip_type_is_ascend_950()) {
1753	            // A5仅支持查询复位请求的发送结果，不支持查询复位状态
1754	            set_ret = dcmi_ipmi_reset_npu_950(device_phy_id);
1755	        } else {
1756	            set_ret = dcmi_ipmi_reset_npu(pcie_slot_id, outband_id);
1757	        }
1758	
1759	        if (set_ret == DCMI_OK && dcmi_board_chip_type_is_ascend_950()) {
1760	            get_ret = DCMI_OK;
1761	            break;
1762	        }
1763	
1764	        if (set_ret == DCMI_OK && !dcmi_board_chip_type_is_ascend_950()) {
1765	            get_ret = dcmi_ipmi_get_npu_reset_state(pcie_slot_id, outband_id, &reset_state);
1766	            if (get_ret == DCMI_OK && reset_state == BMC_RESET_CHIP_SUCCESS) {
1767	                break;
1768	            }
1769	        }
1770	
1771	        gplog(LOG_INFO, "ipmi reset retry. card_id=%d, device_id=%d, set_ret=%d, get_ret=%d, reset_state=%u", card_id,
1772	            device_id, set_ret, get_ret, reset_state);
1773	        sleep(DCMI_RESET_MIN_DELAY); // 频繁复位会导致概率丢芯片
1774	    }
1775	
1776	    if (retry_times == MAX_RETRY_CNT) {
1777	        gplog(LOG_ERR, "ipmi reset failed. card_id=%d, device_id=%d, set_ret=%d, get_ret=%d, reset_state=%d", card_id,
1778	            device_id, set_ret, get_ret, reset_state);
1779	        return DCMI_ERR_CODE_INNER_ERR;
1780	    }
1781	    return DCMI_OK;
1782	}
